#!/usr/bin/env bash
set -euo pipefail

BASE_DIR=${BASE_DIR:-$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")/.." && pwd)}
source "$BASE_DIR/lib/common.sh"

TARGET_HOST=${TARGET_HOST:-${RSYSLOG_TARGET_HOST:-syslog.home.arpa}}
TARGET_PORT=${TARGET_PORT:-${RSYSLOG_TARGET_PORT:-1514}}
TARGET_PROTOCOL=${TARGET_PROTOCOL:-${RSYSLOG_TARGET_PROTOCOL:-udp}}
RSYSLOG_REMOTE_FILE=${RSYSLOG_REMOTE_FILE:-/etc/rsyslog.d/remote_syslog.conf}

build_rsyslog_conf() {
  cat <<EOF_CONF
# Auto-generated by rsyslog_task.sh
module(load="imjournal" StateFile="imjournal.state")
global(localHostname="${Name}")
\$PreserveFQDN on

template(
  name="T_RFC5424"
  type="string"
  string="<%pri%>1 %timegenerated:::date-rfc3339% %hostname% %app-name% %procid% - - %msg%\\n"
)

*.* action(
  type="omfwd"
  target="${TARGET_HOST}"
  port="${TARGET_PORT}"
  protocol="${TARGET_PROTOCOL}"
  Template="T_RFC5424"
  KeepAlive="on"
  ResendLastMSGOnReconnect="on"
)
EOF_CONF
}

remote_script='set -euo pipefail
FILE="$1"
TMP="$(mktemp)"
BACKUP_FILE="${FILE}.bak"

rm -f /etc/rsyslog.d/logstash.*

if command -v apt-get >/dev/null 2>&1; then
  export DEBIAN_FRONTEND=noninteractive
  apt-get update -qq
  apt-get install -y -qq rsyslog sed
elif command -v zypper >/dev/null 2>&1; then
  zypper --non-interactive --quiet install rsyslog sed
else
  echo "Kein unterstützter Paketmanager gefunden" >&2
  exit 1
fi

rm -f /var/log/syslog* /var/log/auth.log* /var/log/cron.log* /var/log/kern.log* /var/log/mail.log* /var/log/user.log*

for f in /etc/rsyslog.d/50-default.conf /etc/rsyslog.conf; do
  [[ -f "$f" ]] || continue
  sed -i -E \
    -e "/^[[:space:]]*#/! s|^([[:space:]]*)(\*\.\*;auth,authpriv\.none[[:space:]]+-?/var/log/syslog)|\1# \2|" \
    -e "/^[[:space:]]*#/! s|^([[:space:]]*)(auth,authpriv\.\*[[:space:]]+/var/log/auth\.log)|\1# \2|" \
    -e "/^[[:space:]]*#/! s|^([[:space:]]*)(cron\.\*[[:space:]]+-?/var/log/cron\.log)|\1# \2|" \
    -e "/^[[:space:]]*#/! s|^([[:space:]]*)(kern\.\*[[:space:]]+-?/var/log/kern\.log)|\1# \2|" \
    -e "/^[[:space:]]*#/! s|^([[:space:]]*)(mail\.\*[[:space:]]+-?/var/log/mail\.log)|\1# \2|" \
    -e "/^[[:space:]]*#/! s|^([[:space:]]*)(user\.\*[[:space:]]+-?/var/log/user\.log)|\1# \2|" \
    "$f"
done

cat > "$TMP"

# imjournal darf nur einmal geladen werden. Laedt eine andere Datei es schon
# (z. B. ein aelterer Drop-in), ist die Gesamtkonfig sonst ungueltig.
other_imjournal=""
for f in /etc/rsyslog.conf /etc/rsyslog.d/*.conf; do
  [[ -f "$f" && "$f" != "$FILE" ]] || continue
  if grep -q -E "^[[:space:]]*module\\(load=\"imjournal\"" "$f"; then
    other_imjournal="$other_imjournal $f"
  fi
done
if [[ -n "$other_imjournal" ]]; then
  echo "FEHLER: imjournal wird bereits geladen in:$other_imjournal" >&2
  echo "        Doppelte Weiterleitung? Datei pruefen und entfernen, dann Task wiederholen." >&2
  rm -f "$TMP"
  exit 1
fi

# Alte Fassung im RAM-nahen Temp sichern, neue einsetzen, Gesamtkonfig pruefen.
# Bei Fehler zurueckrollen: nie eine ungueltige Konfig stehen lassen.
had_old=0
if [[ -f "$FILE" ]]; then
  cp -f "$FILE" "$TMP.old"
  had_old=1
fi
install -D -m 0644 "$TMP" "$FILE"
rm -f "$TMP"

if command -v rsyslogd >/dev/null 2>&1 && ! rsyslogd -N1; then
  echo "FEHLER: rsyslog-Konfiguration ungueltig, rolle zurueck" >&2
  if (( had_old == 1 )); then
    install -m 0644 "$TMP.old" "$FILE"
  else
    rm -f "$FILE"
  fi
  rm -f "$TMP.old"
  exit 1
fi
rm -f "$TMP.old"

# Sicherungen frueherer Laeufe aufraeumen (Backups macht BackupPC).
rm -f "$BACKUP_FILE" "$BACKUP_FILE".*

if command -v systemctl >/dev/null 2>&1; then
  systemctl enable --now rsyslog >/dev/null 2>&1 || true
  systemctl restart rsyslog
else
  service rsyslog restart
fi
'

conf=$(build_rsyslog_conf)
info "Installiere Remote-Syslog auf ${Name} -> ${TARGET_HOST}:${TARGET_PORT}/${TARGET_PROTOCOL}"
printf '%s' "$conf" | run_ssh_with_stdin "$remote_script" "$RSYSLOG_REMOTE_FILE"
